/* ---------- 10 context cards ---------- */
{
  const list = $('#cx-list');
  const chunks = [
    { t:'Brand spacing rule', n:'312 characters', b:'All layout spacing uses multiples of 8. Card padding is 24 on desktop and 16 on mobile.', src:'Brand guidelines.fig', k:'Figma' },
    { t:'Onboarding research', n:'1,180 characters', b:'Five of eight interviewees paused at the workspace step and asked what the team name was used for.', src:'Research summary.pdf', k:'PDF' },
    { t:'Funnel export', n:'940 characters', b:'Weekly sign-ups, first project created and invites sent, split by device and source.', src:'Onboarding funnel.csv', k:'CSV' },
    { t:'Button variants', n:'420 characters', b:'Primary, secondary and ghost buttons share one height scale and the same focus ring.', src:'Component library.fig', k:'Figma' }
  ];
  let pinned = 0;
  function render(f, first){
    const change = () => {
      list.innerHTML = chunks.map((c, i) => ({ c, i })).filter(x => f === 'all' || x.c.k === f).map(({ c, i }, n) =>
        `<div class="ctx-card hatch ${pinned === i ? 'on' : ''} ${first ? '' : 'enter'}" style="animation-delay:${n * 50}ms"><button class="node ${pinned === i ? 'on' : ''}" data-i="${i}"><span class="ctx-top">${ic(c.k === 'Figma' ? 'dashboard' : c.k === 'PDF' ? 'description' : 'grid_on','sm')}<span class="t">${c.t}</span><span class="mono-xs">${c.n}</span></span><span class="ctx-body">${c.b}</span><span class="ctx-src"><span class="kbd k-${c.k}">${c.k}</span>${c.src}</span></button></div>`).join('');
      $$('.node', list).forEach(b => b.addEventListener('click', () => {
        pinned = +b.dataset.i;
        $$('.ctx-card', list).forEach(w => { const on = w.querySelector('.node').dataset.i == pinned; w.classList.toggle('on', on); w.querySelector('.node').classList.toggle('on', on); });
        Sound.play('select');
      }));
    };
    first ? change() : morph(list.parentElement, change);
  }
  initInTabs($('#cx-tabs'), v => render(v));
  render('all', true);
}
